/*
 * Pro tips
 * - After sorting, a minimum absolute-difference pair must occur between adjacent values.
 * - Use one pass to find the minimum gap and another to collect ALL adjacent pairs with that gap.
 * - Duplicates make the minimum zero; retain repeated adjacent pairs as shown in the examples.
 * - Check size < 2 and multiple tied pairs. Compute gaps with long if int extremes are allowed.
 * - This copies the input before sorting. O(n log n) time and O(n) space including the sorted copy and result.
 */

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static List<List<Integer>> minimumDifferencePairs(List<Integer> arr) {
        List<List<Integer>> result = new ArrayList<>();
        if (arr.size() < 2) {
            return result;
        }

        // Sort the array
        List<Integer> sorted = new ArrayList<>(arr);
        sorted.sort(Integer::compareTo);

        // Find minimum difference
        int minDiff = Integer.MAX_VALUE;
        for (int i = 0; i < sorted.size() - 1; i++) {
            int diff = sorted.get(i + 1) - sorted.get(i);
            minDiff = Math.min(minDiff, diff);
        }

        // Collect all pairs with minimum difference
        for (int i = 0; i < sorted.size() - 1; i++) {
            if (sorted.get(i + 1) - sorted.get(i) == minDiff) {
                List<Integer> pair = new ArrayList<>();
                pair.add(sorted.get(i));
                pair.add(sorted.get(i + 1));
                result.add(pair);
            }
        }

        return result;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> arr = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        List<List<Integer>> res = minimumDifferencePairs(arr);
        for (List<Integer> row : res) {
            System.out.println(row.stream().map(String::valueOf).collect(Collectors.joining(" ")));
        }
    }
}
